#!/usr/bin/env node
// Compose an installation's selected module plugins into this Core checkout before a build.
//
//   node --experimental-strip-types scripts/compose-modules.mjs [--selection <file>] [--no-official-modules] [--restore]
//
// The selection file (lancerlogin.modules.json) lives in the installation's private deployment repository. Every plugin
// to compose is fetched at its pinned commit into an isolated directory, validated, and imported by relative path from
// three generated files. Any failure stops composition before a generated file is written, so a plugin is never silently
// dropped. --restore rewrites the generated files to their committed empty defaults.
//
// Official modules: the plugins pinned in scripts/official-modules.json (Outreach first) are composed by default, with or
// without a selection file, unless the selection says "officialModules": false. A selection entry with an official
// module's ID replaces Core's pin. --no-official-modules composes only the selection, for plugin-free development builds
// and tests; without a selection it then changes nothing. Installation and web updates always use the default.
//
// Allowed sources: lancerlogin.plugin-sources.json beside the selection file, when present, limits the sources the
// selection may name, with the Worker's rules. Core's official pins are not checked. An invalid file refuses composition.
import { spawn } from "node:child_process";
import { existsSync } from "node:fs";
import { lstat, mkdir, readFile, readdir, rm, writeFile } from "node:fs/promises";
import { dirname, extname, isAbsolute, join, relative, resolve, sep } from "node:path";
import { fileURLToPath } from "node:url";
import { parseReleaseVersion } from "../packages/shared/src/release-policy.mjs";
import { moduleContractVersion, moduleSdkPackageName, supportedModuleContractVersions } from "../packages/shared/src/module-contract.ts";
import { ModuleMigrationError, loadModuleMigrationPackage, tablesAfterStatements, validateTablePrefix } from "../apps/api/src/module-migrations.ts";
import { SelectionError, allowlistFileName as sharedAllowlistFileName, parseAllowlist, sourceAllowed, maximumSelectedModules, satisfiesCoreRange as sharedSatisfiesCoreRange, parseSelectionFile as parseSharedSelectionFile, pluginTokenVariable as sharedPluginTokenVariable, selectionFileName as sharedSelectionFileName } from "../packages/shared/src/module-selection.ts";

export const coreRoot = resolve(dirname(fileURLToPath(import.meta.url)), "..");
export const selectionFileName = sharedSelectionFileName;
/** The optional source allowlist beside the selection file; the same file and rules the Worker enforces for dashboard changes. */
export const allowlistFileName = sharedAllowlistFileName;
/** Core's pinned list of official plugins, composed by default. */
export const officialModulesFile = "scripts/official-modules.json";
export const pluginTokenVariable = sharedPluginTokenVariable;
export const stagedMigrationManifest = ".provision/module-migrations.json";
const defaultWorkDirectory = ".provision/module-plugins";
const maximumModules = maximumSelectedModules;

const defaultHeader = "// Replaced by module composition for an installation's selected plugins. Core builds without plugins use this empty default.";
const generatedHeader = "// Generated by scripts/compose-modules.mjs for the plugins in lancerlogin.modules.json. Do not commit; restore with npm run compose:modules -- --restore.";
export const generatedFiles = Object.freeze({
  manifests: { path: "packages/shared/src/generated/external-manifests.ts", typeImport: "import type { ModuleDefinition } from \"../module-platform.ts\";", exportName: "externalModuleManifests", type: "readonly ModuleDefinition[]" },
  api: { path: "apps/api/src/generated/external-modules.ts", typeImport: "import type { ApiModuleContribution } from \"../module-contributions.ts\";", exportName: "externalApiModules", type: "readonly ApiModuleContribution<unknown>[]" },
  dashboard: { path: "apps/dashboard/src/generated/external-modules.ts", typeImport: "import type { DashboardModuleContribution } from \"../module-contributions.ts\";", exportName: "externalDashboardModules", type: "readonly DashboardModuleContribution[]" },
});
export const defaultGeneratedContent = (kind) => { const file = generatedFiles[kind]; return `${defaultHeader}\n${file.typeImport}\n\nexport const ${file.exportName}: ${file.type} = [];\n`; };

/** Worker data for selected plugins: reviewed migrations applied through the ledger, and pinned sources recorded in the catalog. */
export const moduleDataFile = "apps/api/src/generated/external-module-data.ts";
const moduleDataTypes = "import type { ModuleMigrationPackage } from \"../module-migrations.ts\";";
export function moduleDataContent(modules = []) {
  const header = modules.length ? generatedHeader : defaultHeader;
  const migrations = modules.map(({ migrations }) => migrations);
  // official: the module ID is one of Core's official modules. selected: the pinned commit came from the installation's
  // selection file rather than Core's official list. Dashboard plugin management uses both to show pending changes.
  const sources = Object.fromEntries(modules.map(({ moduleId, source, commit, official, selected }) => [moduleId, { source, commit, ...(official ? { official: true } : {}), ...(selected ? { selected: true } : {}) }]));
  return `${header}\n${moduleDataTypes}\n\nexport const externalModuleMigrations: readonly ModuleMigrationPackage[] = ${JSON.stringify(migrations, null, 2)};\n\nexport const externalModuleSources: Readonly<Record<string, { readonly source: string; readonly commit: string; readonly official?: boolean; readonly selected?: boolean }>> = ${JSON.stringify(sources, null, 2)};\n`;
}

export class CompositionError extends Error {
  constructor(message) { super(message); this.name = "CompositionError"; }
}
const fail = (message) => { throw new CompositionError(message); };
const isObject = (value) => Boolean(value) && typeof value === "object" && !Array.isArray(value);
const inside = (root, target) => { const path = relative(resolve(root), resolve(target)); return path === "" || path !== ".." && !path.startsWith(`..${sep}`) && !isAbsolute(path); };
const posixPath = (path) => path.split(sep).join("/");
const exactKeys = (value, required, optional, context) => {
  if (!isObject(value)) fail(`${context} must be an object`);
  const unknown = Object.keys(value).filter((key) => !required.includes(key) && !optional.includes(key));
  if (unknown.length) fail(`${context} has unknown keys: ${unknown.join(", ")}`);
  const missing = required.filter((key) => !(key in value));
  if (missing.length) fail(`${context} is missing: ${missing.join(", ")}`);
};

/** Parse lancerlogin.modules.json. file:// sources are accepted only for tests that ask for them explicitly. */
export function parseModuleSelection(text, options = {}) {
  return parseSelectionFile(text, options).modules;
}

/** Selection parsing is shared with the Worker's dashboard plugin management, so both apply identical rules. */
const selectionErrors = (operation) => {
  try { return operation(); } catch (error) { if (error instanceof SelectionError) fail(error.message); throw error; }
};

/**
 * Parse a selection file, including the optional `officialModules` flag (true when absent: compose the official modules).
 * `name` labels errors, so Core's official list reports its own file name.
 */
export function parseSelectionFile(text, options = {}) {
  return selectionErrors(() => parseSharedSelectionFile(text, options));
}

/**
 * The plugins to compose. Core's pinned official plugins come first, unless the selection opts out with
 * "officialModules": false; a selection entry for an official module ID replaces Core's pin, so an installation can hold
 * back or advance one official plugin. Without the official list (composition run with --no-official-modules), this is the
 * selection alone.
 */
export function effectiveSelection({ selection, official, log = () => {} }) {
  if (!official) {
    if (selection?.officialModules !== undefined) log(`${selectionFileName} sets officialModules, but this composition excludes official modules; it was ignored.`);
    return selection?.modules ?? [];
  }
  if (selection?.officialModules === false) { log(`${selectionFileName} opts out of official modules.`); return selection.modules; }
  const chosen = new Map((selection?.modules ?? []).map((entry) => [entry.id, entry]));
  const merged = official.modules.map((entry) => {
    const pinned = chosen.get(entry.id);
    log(pinned ? `Official module ${entry.id} is pinned by ${selectionFileName} at ${pinned.commit}` : `Including official module ${entry.id} at ${entry.commit} (official default; opt out with "officialModules": false)`);
    return pinned ?? entry;
  });
  const sources = new Set(merged.map((entry) => entry.source));
  for (const entry of selection?.modules ?? []) if (!official.modules.some((item) => item.id === entry.id)) {
    if (sources.has(entry.source)) fail(`${selectionFileName} uses ${entry.source}, which is also an official module source`);
    merged.push(entry);
  }
  if (merged.length > maximumModules) fail(`At most ${maximumModules} modules can be composed`);
  return merged;
}

/**
 * Enforce the installation's source allowlist (the text of lancerlogin.plugin-sources.json, or undefined without the file)
 * on every entry of its selection file, with the Worker's rules: host match, then owner match ignoring case when the entry
 * names one. Like the Worker, it checks only sources an installation selects, including a selection entry that pins an
 * official module; Core's own pins in official-modules.json are not selections and are not checked. An invalid file
 * refuses composition even when the selection names no plugin.
 */
export function enforceSourceAllowlist(selection, allowlistText, log = () => {}) {
  if (allowlistText === undefined) return;
  const allowlist = parseAllowlist(allowlistText);
  if (allowlist.state !== "configured") fail(`${allowlist.reason}, so no plugin source is allowed. Repair ${allowlistFileName} in the private deployment repository.`);
  const permitted = allowlist.sources.map((entry) => entry.owner ? `${entry.host}/${entry.owner}` : entry.host).join(", ") || "(none)";
  for (const entry of selection?.modules ?? []) if (!sourceAllowed(entry.source, allowlist)) fail(`Module ${entry.id} source ${entry.source} is not allowed by ${allowlistFileName}, which permits ${permitted}`);
  if (selection?.modules.length) log(`${allowlistFileName} allows every source in ${selectionFileName}`);
}

/** Check a Core release version against a package.json-style range (space-separated comparators, || alternatives). */
export function satisfiesCoreRange(version, range) {
  return selectionErrors(() => sharedSatisfiesCoreRange(version, range));
}

const entryExtensions = { manifest: [".ts", ".js", ".mjs"], api: [".ts", ".js", ".mjs"], dashboard: [".tsx", ".ts", ".jsx", ".js", ".mjs"] };
function pluginPath(pluginRoot, value, context) {
  if (typeof value !== "string" || !value.startsWith("./") || value.includes("\\") || value.split("/").some((segment) => segment === ".." || segment === "") || value.length > 200) fail(`${context} must be a relative path such as ./src/file.ts inside the plugin`);
  const path = resolve(pluginRoot, value);
  if (!inside(pluginRoot, path) || path === resolve(pluginRoot)) fail(`${context} must stay inside the plugin`);
  return path;
}

/** Validate the `lancerlogin` field of a plugin's package.json and resolve its paths inside the plugin. */
export function validatePluginPackage(pkg, { moduleId, pluginRoot, coreVersion }) {
  if (!isObject(pkg)) fail(`Module ${moduleId} package.json must be an object`);
  if (pkg.type !== "module") fail(`Module ${moduleId} package.json must declare "type": "module"`);
  const field = pkg.lancerlogin; const context = `Module ${moduleId} package.json lancerlogin`;
  exactKeys(field, ["moduleId", "contract", "core", "tablePrefix", "entries"], ["migrations", "adoptedCoreMigrations"], context);
  if (field.moduleId !== moduleId) fail(`${context}.moduleId ${JSON.stringify(field.moduleId)} does not match the selected module ${moduleId}`);
  if (!Number.isSafeInteger(field.contract) || field.contract < 1) fail(`${context}.contract must be a positive integer`);
  if (!supportedModuleContractVersions.includes(field.contract)) fail(`Module ${moduleId} needs module contract ${field.contract}; this Core supports contract ${supportedModuleContractVersions.join(", ")}`);
  let compatible;
  try { compatible = satisfiesCoreRange(coreVersion, field.core); } catch (error) { fail(`Module ${moduleId}: ${error.message}`); }
  if (!compatible) fail(`Module ${moduleId} supports LancerLogin core ${field.core}; this Core is ${coreVersion}`);
  let tablePrefix;
  try { tablePrefix = validateTablePrefix(field.tablePrefix); } catch (error) { fail(`Module ${moduleId}: ${error.message}`); }
  exactKeys(field.entries, ["manifest", "api"], ["dashboard"], `${context}.entries`);
  const entries = {};
  for (const [name, value] of Object.entries(field.entries)) {
    const path = pluginPath(pluginRoot, value, `${context}.entries.${name}`);
    if (!entryExtensions[name].includes(extname(path))) fail(`${context}.entries.${name} must be one of ${entryExtensions[name].join(", ")}`);
    entries[name] = path;
  }
  const migrations = field.migrations === undefined ? undefined : pluginPath(pluginRoot, field.migrations, `${context}.migrations`);
  const adopted = field.adoptedCoreMigrations ?? [];
  if (!Array.isArray(adopted) || adopted.some((name) => typeof name !== "string")) fail(`${context}.adoptedCoreMigrations must be an array of Core migration names`);
  return { moduleId, contract: field.contract, core: field.core, tablePrefix, entries, migrations, adoptedCoreMigrations: adopted };
}

// Plugin source scanning. Plugins import only their own files, their declared dependencies, Node or Cloudflare
// built-ins and the module SDK. Anything reaching into Core is refused. This is a development guard for trusted
// code, not a sandbox.
const sourceExtensions = new Set([".ts", ".tsx", ".mts", ".cts", ".js", ".jsx", ".mjs", ".cjs"]);
/**
 * Blank comments while keeping every position, and mark the interior of single- and double-quoted strings, so text such
 * as a route segment "import" or a class name "plan-import" is never read as an import. Template literals stay
 * unmarked, so an expression inside one is still scanned.
 */
function scanSource(source) {
  let output = ""; let index = 0; const quoted = new Uint8Array(source.length + 1);
  while (index < source.length) {
    const char = source[index]; const next = source[index + 1];
    if (char === "/" && next === "/") { const end = source.indexOf("\n", index); const stop = end < 0 ? source.length : end; output += " ".repeat(stop - index); index = stop; continue; }
    if (char === "/" && next === "*") { const end = source.indexOf("*/", index + 2); const stop = end < 0 ? source.length : end + 2; output += source.slice(index, stop).replace(/[^\n]/g, " "); index = stop; continue; }
    if (char === "'" || char === "\"" || char === "`") {
      let cursor = index + 1;
      // Quoted strings end at a newline, so an unusual regular expression literal cannot hide later imports.
      while (cursor < source.length && source[cursor] !== char && (char === "`" || source[cursor] !== "\n")) cursor += source[cursor] === "\\" ? 2 : 1;
      if (char !== "`") quoted.fill(1, index + 1, Math.min(cursor, source.length));
      output += source.slice(index, cursor + 1); index = cursor + 1; continue;
    }
    output += char; index++;
  }
  return { code: output, quoted };
}

export function importSpecifiers(source) {
  const { code, quoted } = scanSource(source); const found = [];
  const statics = [
    /(?<![\w$.])import\s+(?:type\s+)?[^'"`;()]*?\bfrom\s*(['"])([^'"\n]+)\1/g,
    /(?<![\w$.])import\s*(['"])([^'"\n]+)\1/g,
    /(?<![\w$.])export\s+(?:type\s+)?(?:\*(?:\s+as\s+[\w$]+)?|\{[^}]*\})\s*from\s*(['"])([^'"\n]+)\1/g,
  ];
  for (const pattern of statics) for (const match of code.matchAll(pattern)) if (!quoted[match.index]) found.push(match[2]);
  for (const match of code.matchAll(/(?<![\w$.])(import|require)\s*\(\s*/g)) {
    if (quoted[match.index]) continue;
    const rest = code.slice(match.index + match[0].length);
    const literal = /^(['"])([^'"\n]+)\1\s*[,)]/.exec(rest);
    if (!literal) fail(`${match[1]}() must use a string literal so composition can check it`);
    found.push(literal[2]);
  }
  return found;
}

export function checkImportSpecifier(specifier, { file, pluginRoot, dependencies }) {
  const where = `${posixPath(relative(pluginRoot, file))} imports ${JSON.stringify(specifier)}`;
  if (specifier.startsWith("node:") || specifier.startsWith("cloudflare:")) return;
  if (/^[A-Za-z][A-Za-z0-9+.-]*:/.test(specifier) || specifier.startsWith("/") || specifier.includes("\\") || specifier.startsWith("#")) fail(`${where}: absolute, URL and package-internal (#) specifiers are not allowed`);
  if (specifier === "." || specifier === ".." || specifier.startsWith("./") || specifier.startsWith("../")) {
    if (!inside(pluginRoot, resolve(dirname(file), specifier))) fail(`${where}: relative imports must stay inside the plugin`);
    return;
  }
  if (/(^|\/)(apps|packages)\//.test(specifier)) fail(`${where}: Core internals are not importable; use ${moduleSdkPackageName}`);
  const packageName = specifier.startsWith("@") ? specifier.split("/").slice(0, 2).join("/") : specifier.split("/")[0];
  if (packageName === moduleSdkPackageName) return;
  if (packageName.startsWith("@lancerlogin/")) fail(`${where}: Core packages are internal; use ${moduleSdkPackageName}`);
  if (!dependencies.has(packageName)) fail(`${where}: ${packageName} is not a declared dependency of the plugin`);
}

async function walkPlugin(pluginRoot, directory = pluginRoot, files = []) {
  for (const entry of await readdir(directory, { withFileTypes: true })) {
    if (entry.name === ".git" || entry.name === "node_modules") continue;
    const path = join(directory, entry.name);
    const stats = await lstat(path);
    if (stats.isSymbolicLink()) fail(`Plugin contains a symbolic link: ${posixPath(relative(pluginRoot, path))}`);
    if (stats.isDirectory()) await walkPlugin(pluginRoot, path, files);
    else files.push(path);
  }
  return files;
}

export async function scanPluginSources(pluginRoot, pkg) {
  const dependencies = new Set(["dependencies", "devDependencies", "peerDependencies", "optionalDependencies"].flatMap((key) => isObject(pkg[key]) ? Object.keys(pkg[key]) : []));
  for (const file of await walkPlugin(pluginRoot)) {
    const name = file.slice(pluginRoot.length + 1);
    if (/(^|[\\/])(tsconfig[^\\/]*|jsconfig)\.json$/.test(name) && /"(paths|baseUrl|rootDirs)"\s*:/.test(await readFile(file, "utf8"))) fail(`Plugin ${posixPath(name)} must not remap module resolution (paths, baseUrl or rootDirs)`);
    if (!sourceExtensions.has(extname(file))) continue;
    let specifiers;
    try { specifiers = importSpecifiers(await readFile(file, "utf8")); } catch (error) { fail(`${posixPath(name)}: ${error.message}`); }
    for (const specifier of specifiers) checkImportSpecifier(specifier, { file, pluginRoot, dependencies });
  }
}

// External API routes live under the module's own namespace so they cannot shadow Core or another module.
const routeAreas = { workspace: "admin", service: "public", setup: "module-setup" };
function checkExternalManifest(manifest, plugin) {
  const context = `Module ${plugin.moduleId} manifest`;
  if (!isObject(manifest)) fail(`${context} must be an object`);
  if (manifest.id !== plugin.moduleId) fail(`${context} id ${JSON.stringify(manifest.id)} does not match ${plugin.moduleId}`);
  if (manifest.contractVersion !== plugin.contract) fail(`${context} contractVersion must equal the package contract ${plugin.contract}`);
  if (manifest.tablePrefix !== plugin.tablePrefix) fail(`${context} tablePrefix must equal the package tablePrefix ${plugin.tablePrefix}`);
  if (manifest.available !== true) fail(`${context} must be available`);
  if (!Array.isArray(manifest.persistence?.tables) || !Array.isArray(manifest.apiRoutes)) fail(`${context} must declare persistence.tables and apiRoutes`);
  if (!Array.isArray(manifest.persistence.sharedFields) || manifest.persistence.sharedFields.length) fail(`${context} declares sharedFields; external modules keep their data in their own tables`);
  const names = new Set([plugin.moduleId, plugin.tablePrefix.slice(0, -1).replaceAll("_", "-")]);
  for (const route of manifest.apiRoutes) {
    if (route?.match === "pattern") fail(`${context} route ${route.path} uses a pattern; external modules declare exact or prefix routes`);
    const match = /^\/(admin|public|module-setup)\/([a-z][a-z0-9-]*)(?:\/[A-Za-z0-9._~-]+)*$/.exec(route?.path ?? "");
    if (!match || route.path.split("/").some((segment) => segment === "." || segment === "..")) fail(`${context} route ${JSON.stringify(route?.path)} must be /admin/<name>, /public/<name> or /module-setup/<name>`);
    if (!names.has(match[2])) fail(`${context} route ${route.path} must use the module's own name: ${[...names].join(" or ")}`);
    if (routeAreas[route.access] !== match[1]) fail(`${context} route ${route.path} with ${route.access} access must live under /${routeAreas[route.access]}`);
  }
}

/** The one Core-table cleanup step a plugin may declare: deleting its own setup progress, keyed by its module ID. */
export function ownSetupProgressStep(step, moduleId) {
  return isObject(step) && step.kind === "delete" && step.table === "platform_module_setup_progress" && step.where === "module_id=?"
    && Array.isArray(step.bindings) && step.bindings.length === 1 && step.bindings[0] === moduleId && Object.keys(step).length === 4;
}

function checkExternalApi(api, manifest, plugin) {
  if (api.moduleId !== plugin.moduleId) fail(`Module ${plugin.moduleId} API contribution moduleId ${JSON.stringify(api.moduleId)} does not match`);
  if (api.coreRoutes !== undefined) fail(`Module ${plugin.moduleId} API contribution may not use coreRoutes; that is reserved for first-party modules`);
  for (const step of api.cleanup.steps) {
    if (!isObject(step) || !["delete", "reset", "assignments"].includes(step.kind)) fail(`Module ${plugin.moduleId} cleanup step is invalid`);
    if (step.kind !== "assignments" && !manifest.persistence.tables.includes(step.table) && !ownSetupProgressStep(step, plugin.moduleId)) fail(`Module ${plugin.moduleId} cleanup step targets ${JSON.stringify(step.table)}, which is not one of its declared tables`);
  }
}

function routesOverlap(external, other) {
  if (other.match === "pattern") { const pattern = new RegExp(other.path); return pattern.test(external.path) || external.match === "prefix" && pattern.test(`${external.path}/x`); }
  const covers = (prefix, path) => path === prefix || path.startsWith(`${prefix}/`);
  return external.path === other.path || external.match === "prefix" && covers(external.path, other.path) || other.match === "prefix" && covers(other.path, external.path);
}

/** Validate first-party and external manifests and API shapes together through the Core registry and contribution binder. */
export async function validateModuleSet(firstParty, externals) {
  const { createModuleRegistry } = await import("../packages/shared/src/module-platform.ts");
  const { createApiModuleSet } = await import("../apps/api/src/module-contributions.ts");
  const firstPartyIds = new Set(firstParty.map((module) => module.id));
  for (const external of externals) if (firstPartyIds.has(external.plugin.moduleId)) fail(`Module ${external.plugin.moduleId} is a first-party module and cannot be selected as a plugin`);
  // Add externals one at a time so a rejection names the plugin that introduced it.
  for (const [index, external] of externals.entries()) {
    try { createModuleRegistry([...firstParty, ...externals.slice(0, index + 1).map((item) => item.manifest)]); } catch (error) { fail(`Module ${external.plugin.moduleId} conflicts with installed modules: ${error.message}`); }
  }
  const all = [...firstParty, ...externals.map((item) => item.manifest)];
  const registry = createModuleRegistry(all);
  // Compare each plugin with the modules before it, so a clash names the plugin that introduced it.
  for (const [index, external] of externals.entries()) for (const route of external.manifest.apiRoutes) for (const other of [...firstParty, ...externals.slice(0, index).map((item) => item.manifest)]) {
    const clash = other.apiRoutes.find((candidate) => routesOverlap(route, candidate));
    if (clash) fail(`Module ${external.plugin.moduleId} route ${route.path} overlaps module ${other.id} route ${clash.path}`);
  }
  const pages = new Map();
  for (const module of all) for (const page of [...module.navigation, ...module.settings]) {
    if (pages.has(page.path) && pages.get(page.path) !== module.id) fail(`Module ${module.id} dashboard path ${page.path} is already used by module ${pages.get(page.path)}`);
    pages.set(page.path, module.id);
  }
  const stub = async () => undefined;
  const handlers = (names) => Object.fromEntries(names.map((name) => [name, stub]));
  const contributions = [
    ...firstParty.map((module) => ({ moduleId: module.id, coreRoutes: true, setup: { predicates: handlers(module.setup.steps.map((step) => step.id)), stepValid: stub }, jobs: handlers(module.jobs.map((job) => job.id)), reports: handlers((module.reportDatasets ?? []).map((dataset) => dataset.id)), discord: handlers(module.discordCommands.map((command) => command.name)), cleanup: { steps: [{ kind: "assignments" }] } })),
    ...externals.map(({ api }) => ({ moduleId: api.moduleId, routes: handlers(api.routes), setup: { predicates: handlers(api.setupPredicates), stepValid: stub }, jobs: handlers(api.jobs), reports: handlers(api.reports), discord: handlers(api.discord), cleanup: api.cleanup })),
  ];
  // Rebuild the declared shape of each plugin contribution so the Core binder applies its external-module rules exactly as the Worker will.
  for (const [index, { api }] of externals.entries()) {
    const contribution = contributions[firstParty.length + index];
    if (api.privateResponseRoutes !== undefined) contribution.privateResponseRoutes = api.privateResponseRoutes;
    if (api.installationSeed) contribution.installationSeed = () => [];
    if (api.freshEnable) contribution.freshEnable = () => [];
    if (api.backup) contribution.backup = { version: api.backup.version, tables: api.backup.tables, ...Object.fromEntries(api.backup.hooks.map((hook) => [hook, (value) => value])) };
    if (api.reportFilters?.length) contribution.reportFilters = Object.fromEntries(api.reportFilters.map((id) => [id, { options: stub }]));
    if (api.rosterReferences) contribution.rosterReferences = api.rosterReferences;
  }
  try { createApiModuleSet(registry, contributions, { externalModuleIds: new Set(externals.map((external) => external.plugin.moduleId)) }); } catch (error) { fail(error.message); }
  return registry;
}

// Child processes get only what they need. Deployment credentials in this process's environment stay here.
function minimalEnvironment(env) {
  const keep = ["PATH", "PATHEXT", "SystemRoot", "ComSpec", "windir", "HOME", "USERPROFILE", "HOMEDRIVE", "HOMEPATH", "APPDATA", "LOCALAPPDATA", "TEMP", "TMP", "TMPDIR", "LANG", "LC_ALL", "SSL_CERT_FILE", "SSL_CERT_DIR", "NODE_EXTRA_CA_CERTS", "HTTPS_PROXY", "https_proxy", "HTTP_PROXY", "http_proxy", "NO_PROXY", "no_proxy"];
  const allowed = new Set(keep.map((key) => key.toUpperCase()));
  // Match names case-insensitively so Windows' Path and PATH are copied once, under the name the process uses.
  return Object.fromEntries(Object.entries(env).filter(([key, value]) => typeof value === "string" && allowed.has(key.toUpperCase())));
}

/** Git environment for one source. A private-repository token travels only as a transient, host-scoped header. */
export function gitEnvironment(env, source) {
  const result = { ...minimalEnvironment(env), GIT_TERMINAL_PROMPT: "0", GCM_INTERACTIVE: "never" };
  const token = env[pluginTokenVariable];
  const url = new URL(source);
  if (token && url.protocol === "https:") {
    if (!/^[\x21-\x7e]{1,1024}$/.test(token)) fail(`${pluginTokenVariable} contains unsupported characters`);
    Object.assign(result, { GIT_CONFIG_COUNT: "1", GIT_CONFIG_KEY_0: `http.${url.origin}/.extraHeader`, GIT_CONFIG_VALUE_0: `Authorization: Basic ${Buffer.from(`x-access-token:${token}`).toString("base64")}` });
  }
  return result;
}

const redact = (text, env) => { let output = String(text ?? ""); const token = env[pluginTokenVariable]; if (token) { output = output.replaceAll(token, "[redacted]").replaceAll(Buffer.from(`x-access-token:${token}`).toString("base64"), "[redacted]"); } return output; };

export function runCommand(command, args, { cwd, env, timeout = 300_000, redactFrom = {} }) {
  return new Promise((done, reject) => {
    const child = spawn(command, args, { cwd, env, shell: false, stdio: ["ignore", "pipe", "pipe"], windowsHide: true });
    let stdout = ""; let stderr = "";
    const timer = setTimeout(() => child.kill(), timeout);
    child.stdout.on("data", (chunk) => { stdout += chunk; });
    child.stderr.on("data", (chunk) => { stderr += chunk; });
    child.once("error", (error) => { clearTimeout(timer); reject(new CompositionError(`${posixPath(command)} could not start: ${redact(error.message, redactFrom)}`)); });
    child.once("close", (code) => {
      clearTimeout(timer);
      if (code === 0) return done({ stdout, stderr });
      const name = posixPath(command).split("/").pop(); const step = args.find((arg) => !String(arg).startsWith("-") && !String(arg).includes("=") && !isAbsolute(String(arg)) && !String(arg).includes("/")) ?? "";
      reject(new CompositionError(`${name} ${step} failed (${code}): ${redact(stderr.trim().slice(-2000), redactFrom)}`));
    });
  });
}

/** Fetch exactly the pinned commit into an empty directory with no hooks, templates or submodules. */
export async function fetchPinnedPlugin({ source, commit, directory, env, allowFileSources, run = runCommand }) {
  const gitEnv = gitEnvironment(env, source);
  const protocols = ["-c", "protocol.allow=never", "-c", "protocol.https.allow=always", ...allowFileSources ? ["-c", "protocol.file.allow=always"] : []];
  const options = { env: gitEnv, redactFrom: env };
  await run("git", ["init", "--quiet", "--template=", directory], { ...options, cwd: dirname(directory) });
  await run("git", ["-C", directory, ...protocols, "fetch", "--quiet", "--depth=1", "--no-tags", "--no-recurse-submodules", source, commit], { ...options, cwd: directory });
  await run("git", ["-C", directory, "-c", "advice.detachedHead=false", "checkout", "--quiet", "--detach", "FETCH_HEAD"], { ...options, cwd: directory });
  await verifyPinnedCheckout({ directory, commit, env: gitEnv, run });
}

/** The checkout must be exactly the pin, with no symbolic links or submodules. */
export async function verifyPinnedCheckout({ directory, commit, env, run = runCommand }) {
  const head = (await run("git", ["-C", directory, "rev-parse", "HEAD"], { cwd: directory, env })).stdout.trim();
  if (head !== commit) fail(`Plugin checkout is at ${head || "no commit"}, not the pinned commit ${commit}`);
  const status = (await run("git", ["-C", directory, "status", "--porcelain", "--untracked-files=all"], { cwd: directory, env })).stdout.trim();
  if (status) fail(`Plugin checkout at ${commit} differs from the commit`);
  const special = (await run("git", ["-C", directory, "ls-files", "--stage"], { cwd: directory, env })).stdout.split("\n").filter((line) => /^(120000|160000) /.test(line));
  if (special.length) fail(`Plugin at ${commit} contains symbolic links or submodules, which composition does not accept`);
}

function npmCommand(env) {
  const candidates = [env.npm_execpath, join(dirname(process.execPath), "node_modules/npm/bin/npm-cli.js"), join(dirname(process.execPath), "../lib/node_modules/npm/bin/npm-cli.js")];
  const script = candidates.find((candidate) => candidate && candidate.endsWith(".js") && existsSync(candidate));
  return script ? [process.execPath, [script]] : [process.platform === "win32" ? "npm.cmd" : "npm", []];
}

/**
 * Install a plugin's locked runtime dependencies with install scripts disabled. Development dependencies are never
 * installed, and peer dependencies (such as React and the module SDK) always resolve to Core's single copy, so a plugin
 * that declares only peers needs no install.
 */
export async function installPluginDependencies({ pluginRoot, pkg, env, run = runCommand }) {
  const declared = ["dependencies", "optionalDependencies"].some((key) => isObject(pkg[key]) && Object.keys(pkg[key]).length);
  if (!declared) return false;
  if (!existsSync(join(pluginRoot, "package-lock.json"))) fail(`Module ${pkg.lancerlogin?.moduleId} declares dependencies but has no package-lock.json`);
  const [command, prefix] = npmCommand(env);
  await run(command, [...prefix, "ci", "--ignore-scripts", "--omit=dev", "--omit=peer", "--no-audit", "--no-fund"], { cwd: pluginRoot, env: { ...minimalEnvironment(env), npm_config_ignore_scripts: "true", npm_config_update_notifier: "false" }, timeout: 600_000 });
  return true;
}

const semverPattern = /^(\d+)\.(\d+)\.(\d+)(?:[-+][0-9A-Za-z.+-]*)?$/;
const parseSemver = (text) => { const match = semverPattern.exec(String(text)); return match ? match.slice(1, 4).map(Number) : undefined; };
const compareSemver = (left, right) => left[0] - right[0] || left[1] - right[1] || left[2] - right[2];

/** Check an installed version against a peer range: space-separated comparators (^, ~, =, >=, >, <=, <) and || alternatives. */
export function satisfiesPeerRange(version, range) {
  const installed = parseSemver(version);
  if (!installed) return false;
  if (typeof range !== "string" || !range.trim() || range.length > 200) fail("Peer dependency range must be a non-empty string");
  return range.split("||").some((alternative) => alternative.trim().split(/\s+/).every((text) => {
    const match = /^(\^|~|>=|<=|>|<|=)?(\d+\.\d+\.\d+)$/.exec(text);
    if (!match) fail(`Peer dependency range ${JSON.stringify(range)} is not supported; use comparators such as ^1.9.4 or >=1.0.0 <2.0.0`);
    const bound = parseSemver(match[2]); const order = compareSemver(installed, bound);
    switch (match[1] ?? "=") {
      case "^": return order >= 0 && (bound[0] ? installed[0] === bound[0] : bound[1] ? installed[0] === 0 && installed[1] === bound[1] : installed[0] === 0 && installed[1] === 0 && installed[2] === bound[2]);
      case "~": return order >= 0 && installed[0] === bound[0] && installed[1] === bound[1];
      case ">=": return order >= 0;
      case ">": return order > 0;
      case "<=": return order <= 0;
      case "<": return order < 0;
      default: return order === 0;
    }
  }));
}

/** Packages Core provides to plugins as peers, with the versions installed in this Core checkout. */
export async function coreProvidedPackages(root = coreRoot) {
  const readJson = async (path) => { try { return JSON.parse(await readFile(join(root, path), "utf8")); } catch { return undefined; } };
  const provided = new Map();
  const sdk = await readJson("packages/module-sdk/package.json");
  if (sdk?.version) provided.set(moduleSdkPackageName, sdk.version);
  for (const workspace of ["apps/dashboard/package.json", "apps/api/package.json"]) {
    for (const name of Object.keys((await readJson(workspace))?.dependencies ?? {})) {
      const installed = await readJson(`node_modules/${name}/package.json`) ?? await readJson(`${dirname(workspace)}/node_modules/${name}/package.json`);
      if (installed?.version) provided.set(name, installed.version);
    }
  }
  return provided;
}

/** Every peer dependency must be a package Core provides, at a version within the declared range. */
export function checkPeerDependencies(pkg, moduleId, provided) {
  for (const [name, range] of Object.entries(isObject(pkg.peerDependencies) ? pkg.peerDependencies : {})) {
    const version = provided.get(name);
    if (!version) fail(`Module ${moduleId} peer dependency ${name} is not provided by this Core; declare it in dependencies with a lockfile instead`);
    let compatible;
    try { compatible = satisfiesPeerRange(version, range); } catch (error) { fail(`Module ${moduleId}: ${error.message}`); }
    if (!compatible) fail(`Module ${moduleId} needs ${name} ${range}; this Core provides ${name} ${version}`);
  }
}

/** Import the manifest and API entries in a child with a minimal environment and read back their declarations. */
export async function inspectPlugin({ pluginRoot, entries, env, run = runCommand }) {
  const script = join(coreRoot, "scripts/inspect-module-plugin.mjs");
  const { stdout } = await run(process.execPath, ["--experimental-strip-types", "--disable-warning=ExperimentalWarning", script, entries.manifest, entries.api], { cwd: pluginRoot, env: minimalEnvironment(env), timeout: 60_000 });
  try { return JSON.parse(stdout); } catch { fail("Plugin inspection returned invalid output"); }
}

async function readCoreMigrations(root) {
  const directory = join(root, "apps/api/migrations");
  const names = (await readdir(directory)).filter((name) => /^\d+_.+\.sql$/.test(name)).sort();
  return Promise.all(names.map(async (name) => ({ name, content: await readFile(join(directory, name), "utf8") })));
}

const nodeReader = { list: (directory) => readdir(directory), read: (path) => readFile(path, "utf8") };

/** Check module migrations, then require the resulting prefixed tables to equal the manifest's declared tables. */
async function checkPluginMigrations(plugin, manifest, coreMigrations) {
  let pkg;
  try {
    pkg = await loadModuleMigrationPackage(nodeReader, { moduleId: plugin.moduleId, tablePrefix: plugin.tablePrefix, directory: plugin.migrations, adoptedCoreMigrations: plugin.adoptedCoreMigrations, coreMigrations });
  } catch (error) {
    if (error instanceof ModuleMigrationError) fail(error.message);
    if (error?.code === "ENOENT") fail(`Module ${plugin.moduleId} migrations directory is missing`);
    throw error;
  }
  const coreTables = tablesAfterStatements(coreMigrations.map((file) => file.content), [], "Core").filter((table) => table.startsWith(plugin.tablePrefix));
  const tables = tablesAfterStatements(pkg.migrations.flatMap((migration) => migration.statements), coreTables, `Module ${plugin.moduleId}`);
  const declared = [...manifest.persistence.tables].sort();
  if (JSON.stringify(tables) !== JSON.stringify(declared)) fail(`Module ${plugin.moduleId} declares tables ${declared.join(", ") || "(none)"} but its migrations produce ${tables.join(", ") || "(none)"}`);
  return pkg;
}

function relativeImport(fromFile, target) {
  const relativePath = relative(dirname(fromFile), target);
  if (isAbsolute(relativePath)) fail("Plugin checkouts must be on the same drive as the Core checkout");
  const path = posixPath(relativePath);
  return path.startsWith(".") ? path : `./${path}`;
}

export function generatedContent(kind, outputRoot, imports) {
  const file = generatedFiles[kind];
  if (!imports.length) return defaultGeneratedContent(kind);
  const target = join(outputRoot, file.path);
  const lines = imports.map(({ moduleId, path }) => `import module_${moduleId.replaceAll("-", "_")} from ${JSON.stringify(relativeImport(target, path))};`);
  return `${generatedHeader}\n${file.typeImport}\n${lines.join("\n")}\n\nexport const ${file.exportName}: ${file.type} = [${imports.map(({ moduleId }) => `module_${moduleId.replaceAll("-", "_")}`).join(", ")}];\n`;
}

/** Write text, keeping the file's existing line endings so a restored default compares clean in a CRLF checkout. */
async function writeGenerated(path, content) {
  let existing;
  try { existing = await readFile(path, "utf8"); } catch { existing = undefined; }
  const text = existing?.includes("\r\n") ? content.replaceAll("\n", "\r\n") : content;
  if (existing === text) return false;
  await mkdir(dirname(path), { recursive: true });
  await writeFile(path, text);
  return true;
}

const normalized = async (path) => { try { return (await readFile(path, "utf8")).replaceAll("\r\n", "\n"); } catch { return undefined; } };

/** Rewrite generated files to their committed empty defaults and remove the staged migration manifest. */
export async function restoreModuleDefaults({ outputRoot = coreRoot } = {}) {
  const written = [];
  for (const kind of Object.keys(generatedFiles)) {
    const path = join(outputRoot, generatedFiles[kind].path);
    // The dashboard default belongs to the dashboard contract; restore it only where that contract or file exists.
    if (kind === "dashboard" && !existsSync(path) && !existsSync(join(outputRoot, "apps/dashboard/src/module-contributions.ts"))) continue;
    if (await writeGenerated(path, defaultGeneratedContent(kind))) written.push(generatedFiles[kind].path);
  }
  if (await writeGenerated(join(outputRoot, moduleDataFile), moduleDataContent())) written.push(moduleDataFile);
  await rm(join(outputRoot, stagedMigrationManifest), { force: true });
  return written;
}

async function firstPartyModules(root, outputRoot) {
  const path = join(root, generatedFiles.manifests.path);
  if (await normalized(path) !== defaultGeneratedContent("manifests")) {
    // Never import a previous composition's plugin code into this process. Restore the defaults first.
    if (resolve(root) !== resolve(outputRoot)) fail(`${generatedFiles.manifests.path} in Core is not the committed default; run npm run compose:modules -- --restore`);
    await restoreModuleDefaults({ outputRoot });
  }
  const { bundledModuleRegistry } = await import("../packages/shared/src/module-platform.ts");
  return bundledModuleRegistry.modules;
}

async function readAllowlistText(path) {
  try { return await readFile(path, "utf8"); } catch (error) {
    if (error?.code === "ENOENT") return undefined;
    fail(`${allowlistFileName} could not be read, so no plugin source is allowed`);
  }
}

/**
 * Compose the selected plugins. Returns { composed: false } when there is no selection file, leaving every
 * generated file untouched. Otherwise validates everything first and then writes the generated files and the
 * staged migration manifest.
 */
export async function composeModules(options = {}) {
  const root = resolve(options.root ?? coreRoot);
  if (root !== coreRoot) fail("Composition must run from the Core checkout that contains this script");
  const outputRoot = resolve(options.outputRoot ?? root);
  // null means there is no selection file: compose the official modules alone.
  const selectionPath = options.selectionPath === null ? undefined : resolve(options.selectionPath ?? join(root, selectionFileName));
  const workDirectory = resolve(options.workDirectory ?? join(outputRoot, defaultWorkDirectory));
  const env = options.env ?? process.env; const log = options.log ?? ((line) => console.log(line));
  const allowFileSources = options.allowFileSources === true;
  if (inside(workDirectory, outputRoot) || inside(workDirectory, root)) fail("The plugin work directory must be a dedicated subdirectory");

  const official = options.officialModules ? parseSelectionFile(await readFile(resolve(options.officialModulesPath ?? join(root, officialModulesFile)), "utf8"), { allowFileSources, name: "official-modules.json", official: true }) : undefined;
  const selected = selectionPath && existsSync(selectionPath) ? parseSelectionFile(await readFile(selectionPath, "utf8"), { allowFileSources }) : undefined;
  // The allowlist sits beside the selection file in the private deployment repository; without it any source is allowed.
  if (selectionPath) enforceSourceAllowlist(selected, await readAllowlistText(join(dirname(selectionPath), allowlistFileName)), log);
  if (!selected && !official?.modules.length) {
    log(`No ${selectionFileName} found${official ? " and no official modules are pinned" : ""}; composing first-party modules only. Generated module files were left unchanged.`);
    for (const kind of ["manifests", "api"]) if (await normalized(join(outputRoot, generatedFiles[kind].path)) !== defaultGeneratedContent(kind)) log(`${generatedFiles[kind].path} is not the committed default; run npm run compose:modules -- --restore`);
    return { composed: false, modules: [] };
  }
  const selection = effectiveSelection({ selection: selected, official, log });
  const corePackage = JSON.parse(await readFile(join(root, "package.json"), "utf8"));
  const coreVersion = corePackage.version;
  if (!parseReleaseVersion(coreVersion)) fail(`Core package.json version ${coreVersion} is not a release version`);
  const coreMigrations = await readCoreMigrations(root);
  const providedPackages = await coreProvidedPackages(root);
  const firstParty = await firstPartyModules(root, outputRoot);
  for (const entry of selection) if (firstParty.some((module) => module.id === entry.id)) fail(`Module ${entry.id} is a first-party module and cannot be selected as a plugin`);

  await mkdir(workDirectory, { recursive: true });
  const externals = [];
  for (const entry of selection) {
    const pluginRoot = join(workDirectory, entry.id);
    log(`Fetching module ${entry.id} at ${entry.commit}`);
    await rm(pluginRoot, { recursive: true, force: true });
    await fetchPinnedPlugin({ source: entry.source, commit: entry.commit, directory: pluginRoot, env, allowFileSources, run: options.runCommand });
    let pkg;
    try { pkg = JSON.parse(await readFile(join(pluginRoot, "package.json"), "utf8")); } catch { fail(`Module ${entry.id} has no readable package.json at its repository root`); }
    const plugin = validatePluginPackage(pkg, { moduleId: entry.id, pluginRoot, coreVersion });
    for (const [name, path] of Object.entries(plugin.entries)) if (!existsSync(path)) fail(`Module ${entry.id} entry ${name} does not exist`);
    await scanPluginSources(pluginRoot, pkg);
    checkPeerDependencies(pkg, entry.id, providedPackages);
    await installPluginDependencies({ pluginRoot, pkg, env, run: options.installCommand ?? options.runCommand });
    const inspected = await inspectPlugin({ pluginRoot, entries: plugin.entries, env, run: options.runCommand });
    checkExternalManifest(inspected.manifest, plugin);
    checkExternalApi(inspected.api, inspected.manifest, plugin);
    const migrations = await checkPluginMigrations(plugin, inspected.manifest, coreMigrations);
    externals.push({ entry, plugin, pluginRoot, manifest: inspected.manifest, api: inspected.api, migrations });
  }
  await validateModuleSet(firstParty, externals);

  const imports = (name) => externals.filter((external) => external.plugin.entries[name]).map((external) => ({ moduleId: external.plugin.moduleId, path: external.plugin.entries[name] }));
  const dashboardPath = join(outputRoot, generatedFiles.dashboard.path);
  const dashboardContract = existsSync(join(outputRoot, "apps/dashboard/src/module-contributions.ts"));
  if (imports("dashboard").length && !dashboardContract) fail(`Module ${imports("dashboard")[0].moduleId} has a dashboard entry, but this Core has no dashboard module contract`);
  await writeGenerated(join(outputRoot, generatedFiles.manifests.path), generatedContent("manifests", outputRoot, imports("manifest")));
  await writeGenerated(join(outputRoot, generatedFiles.api.path), generatedContent("api", outputRoot, imports("api")));
  if (dashboardContract || existsSync(dashboardPath)) await writeGenerated(dashboardPath, generatedContent("dashboard", outputRoot, imports("dashboard")));
  const officialIds = new Set(official?.modules.map((entry) => entry.id) ?? []);
  const selectedIds = new Set(selected?.modules.map((entry) => entry.id) ?? []);
  await writeGenerated(join(outputRoot, moduleDataFile), moduleDataContent(externals.map(({ entry, plugin, migrations }) => ({ moduleId: plugin.moduleId, source: entry.source, commit: entry.commit, migrations, official: officialIds.has(plugin.moduleId), selected: selectedIds.has(plugin.moduleId) }))));
  const staged = {
    format: 1,
    core: { version: coreVersion, contract: moduleContractVersion },
    modules: externals.map(({ entry, plugin, pluginRoot, migrations }) => ({
      id: plugin.moduleId, source: entry.source, commit: entry.commit, tablePrefix: plugin.tablePrefix,
      directory: plugin.migrations ? posixPath(relative(outputRoot, plugin.migrations)) : null,
      root: posixPath(relative(outputRoot, pluginRoot)),
      adoptedCoreMigrations: plugin.adoptedCoreMigrations,
      baseline: migrations.baseline ?? null,
      migrations: migrations.migrations.map(({ sequence, name, sha256 }) => ({ sequence, name, sha256 })),
    })),
  };
  await mkdir(dirname(join(outputRoot, stagedMigrationManifest)), { recursive: true });
  await writeFile(join(outputRoot, stagedMigrationManifest), `${JSON.stringify(staged, null, 2)}\n`);
  for (const external of externals) log(`Composed module ${external.plugin.moduleId} (${external.migrations.migrations.length} migration(s)${external.migrations.baseline ? ", adopted baseline" : ""})`);
  return { composed: true, modules: externals.map((external) => external.plugin.moduleId), staged };
}

function parseArguments(argv) {
  const options = {}; let restore = false;
  for (let index = 0; index < argv.length; index++) {
    const argument = argv[index];
    const value = () => { const next = argv[++index]; if (!next || next.startsWith("--")) fail(`${argument} needs a value`); return next; };
    if (argument === "--restore") restore = true;
    else if (argument === "--selection") options.selectionPath = value();
    else if (argument === "--output-root") options.outputRoot = value();
    else if (argument === "--work-directory") options.workDirectory = value();
    else if (argument === "--test-allow-file-sources") options.allowFileSources = true;
    else if (argument === "--official-modules") options.officialModules = true;
    else if (argument === "--no-official-modules") options.officialModules = false;
    else if (argument === "--official-list") options.officialModulesPath = value();
    else fail(`Unknown argument ${argument}`);
  }
  return { restore, options };
}

async function main() {
  const { restore, options } = parseArguments(process.argv.slice(2));
  // The command line composes official modules unless told not to; programmatic callers choose explicitly.
  options.officialModules ??= true;
  if (restore) {
    const written = await restoreModuleDefaults({ outputRoot: resolve(options.outputRoot ?? coreRoot) });
    console.log(written.length ? `Restored ${written.join(", ")}` : "Generated module files already match their committed defaults.");
    return;
  }
  // Plugin fetching and installation never see deployment credentials; only the optional plugin token passes.
  const env = Object.fromEntries(Object.entries(process.env).filter(([name]) => name === pluginTokenVariable || !/(CLOUDFLARE|TOKEN|SECRET|PASSWORD|_KEY$|_CODE$|^GITHUB_)/i.test(name)));
  await composeModules({ ...options, env });
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  main().catch((error) => {
    console.error(`Module composition failed: ${redact(error instanceof Error ? error.message : String(error), process.env)}`);
    process.exitCode = 1;
  });
}
